def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    if n == 1:
        return 'D' if opp_last == 'D' else 'C'

    # Tally opponent cooperation across the match.
    opp_coops = 0
    for m, o in history:
        if o == 'C':
            opp_coops += 1
    opp_rate = opp_coops / n

    # Track trailing defection run by opponent.
    tail_def = 0
    for m, o in reversed(history):
        if o == 'D':
            tail_def += 1
        else:
            break

    # Track trailing mutual cooperation run.
    tail_cc = 0
    for m, o in reversed(history):
        if m == 'C' and o == 'C':
            tail_cc += 1
        else:
            break

    # Recent window behavior.
    window = history[-12:] if n >= 12 else history
    wlen = len(window)
    recent_def = 0
    for m, o in window:
        if o == 'D':
            recent_def += 1
    recent_rate = recent_def / wlen

    # Very early: establish cooperation, retaliate lightly.
    if n <= 3:
        if opp_last == 'D':
            return 'D'
        return 'C'

    # Extremely defection-heavy opponent: protect ourselves.
    if opp_rate > 0.75 and recent_rate > 0.6:
        return 'D'

    # Long revenge streak underway: keep punishing.
    if tail_def >= 4:
        return 'D'

    # Established mutual cooperation: preserve it, but occasionally
    # take a cheap shot late in the game (end-of-match exploitation).
    if tail_cc >= 4:
        remaining = 100 - n
        if remaining <= 1:
            return 'D'
        # Very rare probe, only when opponent has shown a forgiving nature.
        if remaining > 5 and opp_rate > 0.85 and rng.random() < 0.03:
            return 'D'
        return 'C'

    # Opponent just defected.
    if opp_last == 'D':
        # If this is an isolated defection after mostly cooperation, give
        # exactly one punishment then return to cooperation.
        if tail_def == 1:
            if opp_rate > 0.7 and tail_cc >= 2:
                # Narrow window: forgive instead of escalating.
                if rng.random() < 0.4:
                    return 'C'
                return 'D'
            return 'D'
        # Two in a row: retaliate firmly.
        if tail_def == 2:
            if opp_rate > 0.6 and rng.random() < 0.2:
                return 'C'
            return 'D'
        # Three in a row (but not 4+, handled above): punish.
        return 'D'

    # Opponent cooperated last.
    # If we just punished and they returned to C, reciprocate warmly.
    if my_last == 'D' and opp_last == 'C':
        return 'C'

    # Opponent is very cooperative overall: cooperate, but be alert
    # for late-game exploitation opportunities only in the final rounds.
    if opp_rate > 0.9:
        remaining = 100 - n
        if remaining <= 1:
            return 'D'
        return 'C'

    # Moderately cooperative opponent.
    if opp_rate > 0.6:
        # If recent trend is worsening, be slightly defensive.
        if recent_rate > 0.4 and rng.random() < 0.3:
            return 'D'
        return 'C'

    # Mixed / cautious opponent.
    if opp_rate > 0.35:
        # Reciprocate last action with mild forgiveness.
        if tail_cc >= 1 and rng.random() < 0.2:
            return 'C'
        if recent_rate < 0.3 and rng.random() < 0.5:
            return 'C'
        return 'D'

    # Mostly defecting opponent: defect, with occasional probes to
    # see if cooperation can be revived.
    remaining = 100 - n
    if remaining <= 1:
        return 'D'
    if rng.random() < 0.1:
        return 'C'
    return 'D'
